$zipPath = Join-Path $PWD "reseller-admin.zip"
$libPath = Join-Path $PWD "mobile\lib"
[IO.File]::WriteAllBytes($zipPath, [Convert]::FromBase64String(($b64 -replace "\s","")))
Expand-Archive -Path $zipPath -DestinationPath $libPath -Force
Remove-Item $zipPath -Force

# Verify files landed
$reseller = Join-Path $libPath "presentation\reseller\reseller_shell.dart"
$admin = Join-Path $libPath "presentation\admin\admin_shell.dart"
if (-not (Select-String -Path $reseller -Pattern "View monthly statement" -Quiet)) {
  Write-Error "Install failed: reseller_shell.dart still looks like placeholder"
}
if (-not (Select-String -Path $admin -Pattern "Approve" -Quiet)) {
  Write-Error "Install failed: admin_shell.dart missing Approve"
}
Write-Host "SUCCESS: Reseller + Admin REAL screens installed"
Write-Host "Verified: View monthly statement + Approve present in files"
Write-Host "Now FULL restart:"
Write-Host "  cd mobile"
Write-Host "  flutter run -d emulator-5554"
